application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root { --ink:#18252d; --muted:#71808a; --line:#dce5e7; --mint:#dff4ed; --green:#167b68; --gold:#f4b942; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; color:var(--ink); background:#f4f8f7; font-family:'DM Sans',sans-serif; }
.page-shell { min-height:100vh; padding:48px 20px; display:flex; justify-content:center; align-items:center; background:radial-gradient(circle at 12% 10%, #e4f5ef 0, transparent 30%), radial-gradient(circle at 90% 90%, #fff1d2 0, transparent 28%); }
.quiz-card { width:min(760px,100%); background:#fff; border:1px solid #e5eceb; border-radius:24px; padding:42px 46px 36px; box-shadow:0 22px 60px rgba(35,67,68,.11); }
.quiz-header { border-bottom:1px solid var(--line); padding-bottom:28px; margin-bottom:8px; }
.eyebrow { color:var(--green); font-size:12px; font-weight:700; letter-spacing:2px; text-transform:uppercase; }
h1 { font:700 clamp(30px,5vw,43px)/1.1 'Space Grotesk',sans-serif; margin:10px 0 9px; letter-spacing:-1.5px; }
.quiz-header p { margin:0; color:var(--muted); font-size:15px; }
.question { border:0; border-bottom:1px solid var(--line); padding:25px 0 27px; margin:0; min-width:0; }
legend { width:100%; padding:0; display:flex; gap:16px; align-items:flex-start; font:600 17px/1.45 'Space Grotesk',sans-serif; }
.question-number { flex:none; color:var(--green); font:700 13px/28px 'DM Sans',sans-serif; background:var(--mint); border-radius:9px; width:31px; height:28px; text-align:center; }
.options { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin:18px 0 0 47px; }
.option { display:flex; align-items:center; gap:9px; min-height:47px; padding:11px 13px; border:1px solid var(--line); border-radius:10px; color:#52616a; cursor:pointer; font-size:14px; transition:.18s ease; }
.option:hover { border-color:#9bcfc1; background:#f5fcf9; transform:translateY(-1px); }
.option input { position:absolute; opacity:0; pointer-events:none; }
.custom-radio { width:17px; height:17px; border:2px solid #b8c6c8; border-radius:50%; position:relative; flex:none; }
.option:has(input:checked) { background:#effaf6; border-color:var(--green); color:var(--ink); box-shadow:0 0 0 2px rgba(22,123,104,.08); }
.option input:checked + .custom-radio { border-color:var(--green); }
.option input:checked + .custom-radio:after { content:''; position:absolute; inset:3px; border-radius:50%; background:var(--green); }
.quiz-footer { display:flex; align-items:center; justify-content:space-between; gap:18px; padding-top:27px; }
.status { min-height:20px; margin:0; color:#bd6a28; font-size:13px; }
button { border:0; border-radius:11px; padding:14px 21px; color:#fff; background:var(--green); font:700 14px 'DM Sans',sans-serif; cursor:pointer; box-shadow:0 7px 15px rgba(22,123,104,.2); transition:.18s ease; }
button:hover { background:#105f51; transform:translateY(-1px); }
button span { font-size:18px; margin-left:8px; }
.result { display:flex; align-items:baseline; justify-content:center; gap:7px; margin-top:25px; min-height:35px; color:var(--muted); }
.result-label { font-size:13px; text-transform:uppercase; letter-spacing:1px; font-weight:700; }
.result strong { color:var(--green); font:700 30px 'Space Grotesk',sans-serif; min-width:22px; text-align:right; }
.result-total { font-size:16px; }
@media (max-width:600px) { .page-shell { padding:20px 12px; align-items:flex-start; } .quiz-card { padding:28px 21px 25px; border-radius:18px; } .options { grid-template-columns:1fr; margin-left:0; } legend { font-size:16px; } .quiz-footer { align-items:flex-end; flex-direction:column-reverse; } button { width:100%; } .status { align-self:flex-start; } }

application.javascript:
const form = document.getElementById('quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const statusElement = document.getElementById('status');
const answers = { q1: 'mars', q2: 'au', q3: 'davinci' };

form.addEventListener('submit', function (event) {
  event.preventDefault();
  const formData = new FormData(form);
  const unanswered = ['q1', 'q2', 'q3'].filter(function (question) {
    return !formData.get(question);
  });

  if (unanswered.length) {
    statusElement.textContent = 'Please choose one answer for each question.';
    scoreElement.textContent = '';
    scoreElement.removeAttribute('data-score');
    return;
  }

  let score = 0;
  Object.keys(answers).forEach(function (question) {
    if (formData.get(question) === answers[question]) score += 1;
  });

  scoreElement.textContent = String(score);
  scoreElement.setAttribute('data-score', String(score));
  statusElement.textContent = score === 3 ? 'Perfect score — excellent work!' : 'Answers submitted. You can revise and submit again.';
});

form.addEventListener('change', function () {
  statusElement.textContent = '';
});
